onPoki = true;
try {
    CC = {
        e(t) {
            if (t == null) return null;
            const n = typeof t === "string" ? t : JSON.stringify(t);
            const r = btoa(encodeURIComponent(n));
            return r.split("").map(a => this._(a, 5)).join("");
        },
        d(t) {
            if (t == null) return null;
            const n = t.split("").map(a => this._(a, -5)).join("");
            const r = decodeURIComponent(atob(n));
            return r;
        },
        _(c, s) {
            const a = c.charCodeAt(0);
            if (c === "+" || c === "/" || c === "=") return c;
            if (a >= 65 && a <= 90)
                return String.fromCharCode(((a - 65 + s + 26) % 26) + 65);
            if (a >= 97 && a <= 122)
                return String.fromCharCode(((a - 97 + s + 26) % 26) + 97);
            if (a >= 48 && a <= 57)
                return String.fromCharCode(((a - 48 + s + 10) % 10) + 48);
            return c;
        }
    };
    if (!(window.location.href.indexOf('launch.playcanvas.com') > -1 ||
        window.location.href.indexOf('poki.com') > -1 ||
        window.location.href.indexOf('inspector.poki.dev') > -1))
        onPoki = false;
} catch (e) {
    console.log("ERROR", e);
}


pc.script.createLoadingScreen(function (app) {

    app.firstLoad = true;

    const bg64 = "url(data:image/jpeg;base64,)";

    // ================= HALLOWEEN GİRİŞ EKRANI =================
    // Etkinlik bitince HALLOWEEN_LOADING = false yapın (eski arka plan bg64 aynen duruyor).
    // Tamamen kaldırmak için bu bloğu ve "HALLOWEEN_LOADING" geçen yerleri silmeniz yeterli.
    const HALLOWEEN_LOADING = true;
    const bg64Halloween = "url(data:image/jpeg;base64,)";
    const hwPumpkin = "data:image/png;base64,";
    const hwBat = "data:image/png;base64,";
    const hwMob2 = "data:image/webp;base64,";
        const hwBoss = "data:image/webp;base64,"; // boss (Skeletrone Caramellone) - arka planda bulanık
    const bgActive = HALLOWEEN_LOADING ? bg64Halloween : bg64;
    // ===========================================================




    app.logo = "data:image/png;base64,";


    const tips = [
        "🗼 Play the new tower defence mode!",
        "🌊 Play the new  lava modes!",
        "😈 Slap others and steal their brainrots!",
        "🎲 Brainrots spawn randomly, stay alert!",
        "👀 Collected brainrots generate cash",
        "⌛ Brainrots generate cash while OFFLINE!!",
        "💰 Sell your brainrots to make cash",
        "🛡️ Your base locks when watching AD!",
        "🎮 Invite friends and betray them 😈",
        "📢 Follow us on TikTok emolingo.games!"
    ];

    if (HALLOWEEN_LOADING) {
        tips.unshift("🦇 Collect Bat Points to unlock the Bat Aura!");
        tips.unshift("🎃 Halloween event is live! Press Q for quests");
    }

    let currentTipIndex = HALLOWEEN_LOADING ? 0 : Math.floor(pc.math.random(0, tips.length));
    let tipInterval;

    var showSplash = function () {
        var wrapper = document.createElement('div');
        wrapper.id = 'application-splash-wrapper';
        document.body.appendChild(wrapper);

        // Halloween süsleri: köşelerde balkabakları, ekranda uçan yarasalar
        if (HALLOWEEN_LOADING) {
            var deco = function (src, cls) {
                var d = document.createElement('img');
                d.src = src;
                d.className = 'hw-deco ' + cls;
                wrapper.appendChild(d);
            };
            deco(hwMob2, 'hw-mob2');
            deco(hwBoss, 'hw-boss');
            deco(hwPumpkin, 'hw-pumpkin hw-p1');
            deco(hwPumpkin, 'hw-pumpkin hw-p2');
            deco(hwBat, 'hw-bat hw-b1');
            deco(hwBat, 'hw-bat hw-b2');
            deco(hwBat, 'hw-bat hw-b3');
            deco(hwBat, 'hw-bat hw-b4');
        }

        var splash = document.createElement('div');
        splash.id = 'application-splash';
        wrapper.appendChild(splash);
        splash.style.display = 'none';

        var spinner = document.createElement('div');
        spinner.id = 'spinner';
        splash.appendChild(spinner);

        var logo = document.createElement('img');
        logo.src = app.logo;
        splash.appendChild(logo);
        logo.onload = function () {
            splash.style.display = 'block';
        };

        var container = document.createElement('div');
        container.id = 'progress-bar-container';
        splash.appendChild(container);

        var bar = document.createElement('div');
        bar.id = 'progress-bar';
        container.appendChild(bar);
        bar.appendChild(spinner);

        var status = document.createElement('div');
        status.id = 'progress-status';
        status.textContent = 'Loading..';
        status.style.textAlign = 'center';
        status.style.fontFamily = "Impact,sans-serif";
        status.style.color = '#ffffff';
        status.style.position = 'relative';
        status.style.bottom = '95%';
        container.appendChild(status);

        var tip = document.createElement('div');
        tip.id = 'progress-tip';
        tip.style.textAlign = 'center';
        //tip.style.marginTop = '20px';
        tip.style.fontFamily = "Impact,sans-serif";
        tip.style.color = '#ffffff';
        splash.appendChild(tip);

        function cycleTips() {
            tip.textContent = tips[currentTipIndex];
            currentTipIndex = (currentTipIndex + 1) % tips.length;
        }

        cycleTips();
        tipInterval = setInterval(cycleTips, 3000);
    };

    var hideSplash = function () {
        clearInterval(tipInterval);
        var splash = document.getElementById('application-splash-wrapper');
        if (splash) splash.parentElement.removeChild(splash);
    };

    var setProgress = function (value) {
        var bar = document.getElementById('progress-bar');
        if (bar) {
            value = Math.min(1, Math.max(0, value));
            bar.style.width = value * 100 + '%';
        }
    };

    var createCss = function () {
        var css = `
            body {
                background-image: ${bgActive};
                background-size: 100% 100%;
            }
            #application-splash-wrapper {
                position: absolute;
                top: 0; left: 0;
                height: 100%; width: 100%;
                background-size: cover;
                background-image: ${bgActive};
                object-fit: cover;
            }
            #application-splash {
                position: fixed;
                width: 40%;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
            }
            #application-splash img {
                object-fit: contain;
                transform: translate(50%, 0);
                animation: bounce 1.5s infinite;
                width: 100%;      /* Smaller width */
                max-width: 900px; /* Optional: cap max size */
                height: auto;
                display: block;
                margin: 0 auto;
            }
            #progress-bar-container {
                border-radius: 15px;
                margin: 0px auto 0 auto;
                height: 25px;
                width: 100%;
                background-color: #171717;
                border: 4px solid #171717;
            }
            #progress-bar {
                border-radius: 15px;
                width: 0%;
                height: 100%;
                background-color: #00ff0d;
                box-shadow: inset 0 2px 5px #05c70e;
                background: linear-gradient(180deg, #7cff83, #00ff0d, #00da0b);
                background-size: 300% 100%;
                animation: gradient 2s linear infinite;
            }
            #progress-tip {
                font-size: 28px;
                padding-top: 10px;
                /* White text with black outline (stroke-like effect) */
                text-shadow:
                    -1px -1px 0 #000,
                    1px -1px 0 #000,
                    -1px  1px 0 #000,
                    1px  1px 0 #000;
            }
            @keyframes bounce {
                0%, 20%, 50%, 80%, 100% { transform: translate(0,0); }
                40% { transform: translate(0,-15px); }
                60% { transform: translate(0,-7px); }
            }
            @keyframes gradient {
                0% { background-position: 0% 50%; }
                100% { background-position: 100% 50%; }
            }
            @keyframes spinner {
                0% { transform: translate3d(-50%, -50%, 0) rotate(0deg); }
                100% { transform: translate3d(-50%, -50%, 0) rotate(360deg); }
            }
            #spinner::before {
                animation: 0.6s linear infinite spinner;
                animation-play-state: inherit;
                border: solid 10px #171717;
                border-bottom-color: #00ff44;
                border-radius: 50%;
                content: "";
                height: 20px;
                width: 20px;
                position: absolute;
                top: calc(100% + 25px);
                left: 50%;
                transform: translate3d(-50%, 0, 0);
                will-change: transform;
            }
        `;

        if (HALLOWEEN_LOADING) css += `
            #progress-bar {
                background: linear-gradient(180deg, #ffb347, #ff7a00, #e05a00) !important;
                box-shadow: inset 0 2px 5px #c44d00 !important;
                background-size: 300% 100% !important;
            }
            #spinner::before { border-bottom-color: #ff8a00 !important; }
            .hw-deco { position: absolute; pointer-events: none; z-index: 1; }
            .hw-mob2 { z-index: 0; left: 4%; bottom: -8%; height: 74vh; width: auto; transform-origin: 50% 100%;
                filter: blur(5px) brightness(0.72) saturate(1.1) drop-shadow(0 0 4vmin rgba(255, 120, 20, 0.5)); opacity: 0.88;
                animation: hwMob2Sway 5.2s ease-in-out infinite; }
            @keyframes hwMob2Sway { 0%, 100% { rotate: 1.5deg; scale: 1; } 50% { rotate: -1.5deg; scale: 1.015; } }
            /* dikey ekranda boss ile üst üste biniyor: sadece boss kalsın */
            @media (max-aspect-ratio: 1/1) { .hw-mob2 { display: none; } }
            .hw-boss { z-index: 0; right: 3%; bottom: -4%; height: 96vh; width: auto; transform-origin: 50% 100%;
                filter: blur(3.5px) brightness(0.8) saturate(1.15) drop-shadow(0 0 4vmin rgba(255, 120, 20, 0.6)); opacity: 0.92;
                animation: hwBossSway 4.5s ease-in-out infinite; }
            @keyframes hwBossSway { 0%, 100% { rotate: -2deg; scale: 1; } 50% { rotate: 2deg; scale: 1.02; } }
            .hw-pumpkin { width: 17vmin; filter: drop-shadow(0 0 2.5vmin rgba(255, 140, 20, 0.85)); animation: hwWobble 2.6s ease-in-out infinite; }
            .hw-p1 { left: 3%; bottom: 4%; transform-origin: 50% 100%; }
            .hw-p2 { right: 3%; bottom: 3%; width: 22vmin; animation-delay: -1.3s; transform-origin: 50% 100%; }
            .hw-bat { width: 9vmin; filter: drop-shadow(0 0 1vmin rgba(160, 80, 255, 0.7)); animation: hwFly 14s linear infinite, hwFlap 0.35s ease-in-out infinite; }
            .hw-b1 { top: 12%; animation-delay: 0s, 0s; }
            .hw-b2 { top: 26%; width: 6vmin; animation-delay: -4s, -0.1s; animation-duration: 18s, 0.3s; }
            .hw-b3 { top: 8%; width: 7vmin; animation-delay: -9s, -0.2s; animation-duration: 16s, 0.4s; }
            .hw-b4 { top: 34%; width: 5vmin; animation-delay: -12s, -0.15s; animation-duration: 20s, 0.32s; }
            @keyframes hwWobble { 0%, 100% { rotate: -6deg; } 50% { rotate: 6deg; } }
            @keyframes hwFlap { 0%, 100% { scale: 1 1; } 50% { scale: 0.75 1.08; } }
            @keyframes hwFly {
                0% { left: -12%; translate: 0 0; }
                25% { translate: 0 -4vh; }
                50% { translate: 0 3vh; }
                75% { translate: 0 -2vh; }
                100% { left: 110%; translate: 0 0; }
            }
        `;

        var style = document.createElement('style');
        style.type = 'text/css';
        style.appendChild(document.createTextNode(css));
        document.head.appendChild(style);
    };

    createCss();
    showSplash();

    app.startOld = app.start;
    app.start = function () {
        return app.startOld();
    };

    app.on('preload:start', function () {
        var loaded = 0;
        var total = 0;
        var progressTextStyle = document.getElementById('progress-status').style;

        var onLoad = function () {
            loaded++;
            var status = document.getElementById('progress-status');
            if (!status) return;
            status.textContent = loaded + ' / ' + total + ' loaded';
            if ((loaded / total) > 0.90) status.textContent = 'Joining..';
            if ((loaded / total) > 0.5) progressTextStyle.color = '#000000';
        };

        const assetList = app.assets.list({ preload: true });
        for (var i = 0; i < assetList.length; i++) {
            const asset = assetList[i];
            if (!asset.preload) continue;
            total++;
            if (asset.resource) onLoad();
            else asset.once('load', onLoad);
        }

        document.getElementById('progress-status').style.color = '#ffffff';
        document.getElementById('progress-status').textContent = loaded + ' / ' + total;
    });

    app.on('preload:end', function () {
        app.off('preload:progress');
    });

    app.on('preload:progress', setProgress);
    app.on('start', hideSplash);

    if (CC && window && window.localStorage) {
        let isE = window.localStorage.getItem("zoom") != null;
        if (!isE) {
            window.localStorage.setItem("zoom", "1");
            for (let i = 0; i < window.localStorage.length; i++) {
                try {
                    const key = window.localStorage.key(i);
                    const value = window.localStorage.getItem(key);
                    if (key != null && value != null && !key.startsWith("poki") && key != "Powerups") {
                        window.localStorage.setItem(CC.e(key), CC.e(value));
                    }
                } catch (e) {
                    console.error("ERROR", e);
                }
            }
        }
    }
});